CREATE TABLE IF NOT EXISTS vip_preferences(player_uuid UUID PRIMARY KEY,nickname VARCHAR(16),chat_color VARCHAR(16));
CREATE TABLE IF NOT EXISTS vip_command_uses(player_uuid UUID NOT NULL,command VARCHAR(32) NOT NULL,last_use TIMESTAMPTZ NOT NULL,PRIMARY KEY(player_uuid,command));
CREATE TABLE IF NOT EXISTS vip_warps(name VARCHAR(16) PRIMARY KEY,world TEXT NOT NULL,x DOUBLE PRECISION NOT NULL,y DOUBLE PRECISION NOT NULL,z DOUBLE PRECISION NOT NULL,yaw REAL NOT NULL,pitch REAL NOT NULL);
GRANT SELECT,INSERT,UPDATE ON vip_preferences,vip_command_uses,vip_warps TO atlas_app;
